// Danh sach symbol va khung nen can lay, moi combo lay dung ~1 thang gan nhat
const symbols = ['BTCUSDT', 'ETHUSDT', 'SOLUSDT'];
const intervals = [
  { interval: '1h', limit: 720, timeframe: '1h' },
  { interval: '4h', limit: 180, timeframe: '4h' },
  { interval: '1d', limit: 31,  timeframe: '1d' }
];

const allRows = [];

for (const symbol of symbols) {
  for (const cfg of intervals) {
    const url = `https://api.binance.com/api/v3/klines?symbol=${symbol}&interval=${cfg.interval}&limit=${cfg.limit}`;
    let candles;
    try {
      const res = await fetch(url);
      candles = await res.json();
    } catch (e) {
      allRows.push({ json: { error: true, symbol, timeframe: cfg.timeframe, message: e.message } });
      continue;
    }
    if (!Array.isArray(candles)) {
      allRows.push({ json: { error: true, symbol, timeframe: cfg.timeframe, message: JSON.stringify(candles) } });
      continue;
    }
    for (const k of candles) {
      allRows.push({
        json: {
          symbol,
          timeframe: cfg.timeframe,
          open_time: new Date(k[0]).toISOString(),
          open: parseFloat(k[1]),
          high: parseFloat(k[2]),
          low: parseFloat(k[3]),
          close: parseFloat(k[4]),
          volume: parseFloat(k[5]),
          source: 'binance'
        }
      });
    }
  }
}

return allRows;

const items = $input.all();
const errorItems = items.filter(i => i.json && i.json.error);
const meta = $('Set Workflow Meta').first().json;
return [{
  json: {
    workflow_id: meta.workflow_id,
    status: errorItems.length > 0 ? "partial_error" : "success",
    total_rows: items.length,
    error_count: errorItems.length,
    started_at: meta.started_at
  }
}];
